def difference(d1, d2, level=-1):
    result = {}
    if level == 0:
        for key in d1:
            if key not in d2:
                result[key] = d1[key]
        for key in d2:
            if key not in d1:
                result[key] = d2[key]
    else:
        for key in d1:
            if key in d2 and level == 1:
                if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                    child_result = difference(d1[key], d2[key], level - 1)
                    if not child_result:
                        continue
                    for sub_key, sub_value in child_result.items():
                        if sub_key not in result:
                            result[sub_key] = sub_value
            else:
                result[key] = d1[key]
    return result
