def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, field_info in observer_schema.items():
        if field not in response:
            raise KeyError(f"'{field}' is not present in the Kubernetes response")

        if type(response[field]) not in field_info['types']:
            raise ValueError(f"'{field}' type mismatch in response {type(response[field])} for field '{field}'")

        if field_info['all_fields']:
            for subfield, subfield_info in field_info['all_fields'].items():
                if subfield not in response[field]:
                    raise KeyError(f"'{subfield}' is not present in the Kubernetes response")
                if type(response[field][subfield]) not in subfield_info['types']:
                    raise ValueError(f"'{subfield}' type mismatch in response {type(response[field][subfield])} for subfield '{subfield}'")

        if field_info['type'] == 'Dictionary':
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], field_info['schema'], response[field])
        elif type(last_applied_manifest[field]) == dict:
            for subfield, subfield_info in field_info['schema'].items():
                if subfield not in last_applied_manifest[field] or type(last_applied_manifest[field][subfield]) != field_info['types'][subfield]:
                    raise ValueError(f"'{subfield}' type mismatch in last_applied_manifest {type(last_applied_manifest[field][subfield])} for subfield '{subfield}'")

    last_applied_manifest.update(response)
