from typing import AnyStr, Optional, Union, List

class SQLParams:
    in_style: str
    bind_style: str
    keywords: Optional[List[str]]

class FormatManyError(Exception):
    pass

def formatmany(sql: AnyStr, many_params: Union[Iterable[Dict[str, Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[str, Any]], List[Sequence[Any]]]]:
    if not isinstance(sql, (str, bytes)):
        raise FormatManyError("SQL query must be a string or bytes")

    if not isinstance(many_params, (list, tuple)):
        raise FormatManyError("Parameters must be an iterable")

    in_style = SQLParams.in_style
    bind_style = SQLParams.bind_style
    keywords = SQLParams.keywords

    formatted_sql, converted_params = sql, []

    if in_style == 'named':
        for params in many_params:
            if not isinstance(params, dict):
                raise FormatManyError("Each parameter must be a dictionary when in-style is named")
            converted_params.append(params)
    elif in_style == 'ordinal':
        for params in many_params:
            if not isinstance(params, (list, tuple)):
                raise FormatManyError("Each parameter must be a list or tuple when in-style is ordinal")
            if len(params) != len(SQLParams.bind_style_params):
                raise FormatManyError("Each parameter list or tuple must have the same number of elements as the bind style parameters")
            converted_params.append(params)
    else:
        raise FormatManyError("Invalid in-style. Must be 'named' or 'ordinal'")

    converted_query = formatted_sql.substitute(params=list(converted_params))
    return formatted_query, converted_params
