def absorb(self, args):
    if not isinstance(args, list):
        raise ValueError("Input must be a list of expressions")
    if all(not isinstance(x, Expression) for x in args):
        raise ValueError("All elements of args must be expressions")

    new_args = []

    for expr in args:
        # Apply absorption
        if expr.is_and():
            absorption_exprs = expr.get_operands()
            if abs(a.expr for a in absorption_exprs) == abs(b.expr for b in absorption_exprs):
                new_args.append(expr.invert())
        # Apply negative absorption
        elif expr.is_or():
            absorption_exprs = expr.get_operands()
            if ~(abs(a.expr for a in absorption_exprs)) == ~~(abs(b.expr for b in absorption_exprs)):
                new_args.append(expr.invert())

    return new_args
