import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0
    if platform not in [1, 0]:
        raise ValueError("Invalid platform value")

    # Normalize whitespace for cross-platform compatibility
    s = s.replace('\r\n', '\n').replace('\r', '\n').replace('\f', '\n').replace('\v', '\n')

    # Split according to POSIX rules
    if platform == 1:
        return re.split(r'\s+', s, maxsplit=-1)

    # Split according to Windows cmd rules (uses a different regex)
    elif platform == 0:
        return re.split(r'(?<!\\)\s+', s, maxsplit=-1)

    # Handle other values (reserved)
    raise ValueError("Invalid platform value")
