def parse_frequency(frequency):
    if frequency is None or frequency.lower() == 'always':
        return None
    try:
        # Extract the number from the frequency string
        number = int(frequency[:frequency.index(' ')])

        # Extract the unit of time from the frequency string
        unit = frequency[frequency.index(' '):]

        # Convert the unit of time to its corresponding datetime.timedelta unit
        if unit == 'seconds':
            return datetime.timedelta(seconds=number)
        elif unit == 'minutes':
            return datetime.timedelta(minutes=number)
        elif unit == 'hours':
            return datetime.timedelta(hours=number)
        elif unit == 'days':
            return datetime.timedelta(days=number)
        elif unit == 'weeks':
            return datetime.timedelta(weeks=number)
        elif unit == 'months':
            return datetime.timedelta(days=number * 30)
        elif unit == 'years':
            return datetime.timedelta(days=number * 365)
        else:
            raise ValueError(f"Unsupported unit: {unit}")
    except ValueError as e:
        raise ValueError(f"Failed to parse frequency: {frequency}: {e}")
