import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    processes = []
    for cmd in commands:
        # Create a subprocess object for each command
        process = subprocess.Popen([cmd] + args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
        processes.append(process)

    try:
        if verbose:
            # Display command output as it is being run
            for process in processes:
                while process.stdout.readline():
                    sys.stdout.write(process.stdout.readline().decode())
                    if not hide_stderr:
                        sys.stdout.write(process.stderr.readline().decode())

    except subprocess.CalledProcessError as e:
        # Handle exceptions that have a status code greater than 0
        err_message = "Command failed with exit code: {}\n{}".format(e.returncode, e.stderr.decode())
        if not verbose:
            print(err_message)

    finally:
        try:
            # Clean up by waiting for all processes to complete
            for process in processes:
                process.wait()
        except KeyboardInterrupt:
            # Optionally handle process cleanup when the program is interrupted
            for process in processes:
                process.terminate()
