    if not hasattr(iface, '__dict__') or not hasattr(iface, '__slots__') or len(iface.__slots__) > 0:
        raise ValueError("iface must be a regular class")
    for prop_name, prop_type in iface.__dict__.items():
        if not hasattr(candidate, prop_name) or not (isinstance(getattr(candidate, prop_name), prop_type) if prop_type else True):
            if tentative:
                print(f"Warning: Property {prop_name} does not match {iface.__dict__[prop_name]}")
            else:
                raise ValueError(f"Property {prop_name} in candidate does not match iface({iface.__dict__[prop_name]})")
