def pop(self, key, default=__marker):
    if not self._check_key(key):
        raise KeyError(key)
    if key in self._data:
        ret = self._data[key]
        del self._data[key]
        return ret
    elif default is __marker:
        raise KeyError(key)
    else:
        return default
