from typing import Tuple, Set, Callable

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set[str], str]:
    tags = set()
    current_tag = False
    tag_name = ""

    result = []

    for char in text:
        if char == "(":
            current_tag = True
            tag_name = ""
        elif char == ")":
            current_tag = False
            if tag_name:
                tags.add(tag_name)
        elif current_tag:
            tag_name += char
        else:
            result.append(char)

    result_str = ''.join(result)

    if replacer:
        result_str = replacer(result_str)

    return tags, result_str
```

