def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type
    :param settings_dirs: List of directory paths where the .ini files are located
    :param spec_option: Specifies the type of directives to be listed
    :return: a list of file names associated with the specifications.

    Raises:
    FileNotFoundError: If a .ini file does not exist at a specified directory.
    PermissionError: If the user lacks the necessary permissions to access a .ini file.
    """
    # Step 1: Validate the input types
    if not isinstance(settings_dirs, list) or not all(isinstance(dir, str) for dir in settings_dirs):
        raise TypeError("Invalid type for settings_dirs. Expected a list of strings.")
    if not isinstance(spec_option, str) or spec_option not in ['basic', 'extended']:
        raise ValueError("Invalid value for spec_option. Expected 'basic' or 'extended'.")

    # Step 2: Retrieve the list of .ini files
    result = []
    try:
        for dir in settings_dirs:
            for root, _, files in os.walk(dir):
                for file in files:
                    if file.endswith('.ini'):
                        spec_file_path = os.path.join(root, file)
                        # Process the file (e.g., extract directives based on spec_option)
                        result.append(spec_file_path)
    except FileNotFoundError as e:
        raise FileNotFoundError(f"File not found: {e}")
    except PermissionError as e:
        raise PermissionError(f"Permission denied: {e}")

    return result
```

