import os
import yaml

class IRValidatorException(Exception):
    pass

class YAMLReader:
    @staticmethod
    def validate_from_file(yaml_file=None):
        # Default to current working directory if no file is provided
        if yaml_file is None:
            yaml_file = os.getcwd()

        # Check if file exists
        if not os.path.exists(yaml_file) or not os.path.isfile(yaml_file):
            raise FileNotFoundError(f"File {yaml_file} not found.")

        # Load the YAML file
        try:
            with open(yaml_file, 'r') as file:
                data = yaml.safe_load(file)
        except yaml.YAMLError as error:
            raise IRValidatorException(f"Error in YAML file: {error}")

        # Validate the data
        for key, value in data.items():
            if key == 'mandatory_field' and value is None:
                raise IRValidatorException(f"Missing mandatory field '{key}' in YAML file.")

        return data
