def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_conditions = set()
    for option_spec in options_spec:
        if 'required_when' in option_spec:
            required_when = option_spec['required_when']
            condition_met = all(arg in args for arg in required_when)
            if condition_met:
                required_conditions.add(option_spec['arg'])

    return list(required_conditions)
