import subprocess
import os

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    playbook_dir = os.path.dirname(playbook_path)
    args = ['ansible-playbook']
    if verbose is not None:
        args.append('-v' + str(verbose))
    if extra_vars is not None:
        args.extend(['--extra-vars=', str(extra_vars)])
    args.extend(['-i', f'{ir_workspace.workdir}/{ir_plugin.get_inventory()}'])
    args.append(playbook_path)
    if ansible_args is not None:
        args.extend(ansible_args)

    try:
        result = subprocess.run(args, cwd=playbook_dir, check=True, capture_output=True, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        if e.stderr:
            return e.stderr
        return e.stdout if e.stdout else ''
