import os

def get_plugin_spec_flatten_dict(plugin_dir):
    if not os.path.exists(plugin_dir):
        raise FileNotFoundError(f"The specified directory '{plugin_dir}' does not exist.")

    plugin_spec = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            file_path = os.path.join(root, file)
            if file.endswith(".py"):
                with open(file_path, "rb") as file:
                    exec(file.read(), plugin_spec)

    ordered_keys = sorted(plugin_spec.keys())
    flatten_dict = {key: plugin_spec[key] for key in ordered_keys}

    return flatten_dict
```

